-- One year of demo data for reports (DemoYearSeeder), as a plain SQL import for the live server.
-- Generated 2026-11-23 08:18 from the local database. Dates run 2025-11-29 20:56:32 → 2026-11-22 22:24:24.
-- Needs: all migrations, a Super Admin, the VIP plans growth / professional / growth-plus / premium,
--        cities lucknow / jhansi / pune / mumbai / hyderabad / bengaluru.
-- Photos ship with the code in storage/app/public/uploads/demo/year (deploy before importing).
-- Re-runnable: it first removes its own earlier copy (users on @demo.globallife.co.in or in the staff list below) and nothing else.
-- New ids start after the current maximum of each table, so existing data is never overwritten.
-- All demo logins use the password Password!123.
SET NAMES utf8mb4;
START TRANSACTION;

-- ===================== 1. remove an earlier copy (cascades remove pages, orders' lines, payslips …)
DROP TEMPORARY TABLE IF EXISTS demo_users; CREATE TEMPORARY TABLE demo_users (id BIGINT UNSIGNED PRIMARY KEY);
DROP TEMPORARY TABLE IF EXISTS demo_sites; CREATE TEMPORARY TABLE demo_sites (id BIGINT UNSIGNED PRIMARY KEY);
DELETE FROM `orders` WHERE user_id IN (SELECT id FROM demo_users) OR fulfilled_by_microsite_id IN (SELECT id FROM demo_sites);
DELETE FROM `leads` WHERE email LIKE '%@demo.globallife.co.in' OR vip_microsite_id IN (SELECT id FROM demo_sites);
DELETE FROM `assets` WHERE asset_tag IN ('GLD-DT-0001', 'GLD-DT-0002', 'GLD-DT-0003', 'GLD-DT-0004', 'GLD-FN-0001', 'GLD-LT-0001', 'GLD-LT-0002', 'GLD-LT-0003', 'GLD-LT-0004', 'GLD-LT-0005', 'GLD-LT-0006', 'GLD-LT-0007', 'GLD-LT-0008', 'GLD-MB-0001', 'GLD-MB-0002', 'GLD-MB-0003', 'GLD-OT-0001', 'GLD-SIM-0001', 'GLD-SIM-0002', 'GLD-VH-0001');
DELETE FROM `announcements` WHERE title IN ('Year-end closing schedule', 'Republic Day celebration', 'Holi holiday and office timing', 'New financial year — investment declarations', 'Welcome Pallavi Dubey', 'Health check-up camp', 'Diwali bonus and office celebration');
DELETE FROM `payslips` WHERE employee_id IN (SELECT id FROM `employees` WHERE user_id IN (SELECT id FROM demo_users));
DELETE r FROM `payroll_runs` r LEFT JOIN `payslips` p ON p.payroll_run_id = r.id WHERE p.id IS NULL AND r.month IN ('2025-12', '2026-01', '2026-02', '2026-03', '2026-04', '2026-05', '2026-06', '2026-07', '2026-08', '2026-09', '2026-10');
DELETE FROM `model_has_roles` WHERE model_type = 'App\\Models\\User' AND model_id IN (SELECT id FROM demo_users);
DELETE FROM `model_has_permissions` WHERE model_type = 'App\\Models\\User' AND model_id IN (SELECT id FROM demo_users);
DELETE FROM `users` WHERE id IN (SELECT user_id FROM `vip_microsites` WHERE id IN (SELECT id FROM demo_sites));
DELETE FROM `users` WHERE id IN (SELECT id FROM demo_users);

