INSERT INTO `vip_microsites` (`id`, `user_id`, `city_id`, `vip_plan_id`, `business_name`, `business_category`, `business_sub_category`, `owner_name`, `business_slug`, `description`, `short_description`, `establishment_year`, `gst_no`, `pan_no`, `cin_no`, `logo_path`, `cover_banner_path`, `business_email`, `phone_number`, `alternate_number`, `whatsapp_number`, `website_url`, `address`, `google_map_url`, `business_hours`, `holidays`, `facebook_url`, `instagram_url`, `youtube_url`, `linkedin_url`, `twitter_url`, `telegram_url`, `pinterest_url`, `module_visibility`, `page_layout`, `secure_token`, `status`, `activated_at`, `plan_expires_at`, `created_at`, `updated_at`) VALUES
(@o_vip_microsites+1, @o_users+24, @cities_1, @vip_plans_8, 'Shree Krishna Mishthan Bhandar', 'Sweets & Bakery', 'Sweet Shop & Namkeen', 'Ramesh Agrawal', 'shree-krishna-mishthan-bhandar', 'Three generations of the Agrawal family have run Shree Krishna Mishthan Bhandar from the same corner of Sadar Bazaar.\n\nEvery sweet is made in small batches with pure desi ghee and milk from our own dairy partners. Festive gift boxes, wedding orders and corporate Diwali hampers are packed in-house and delivered across Jhansi.', 'Pure desi-ghee sweets and fresh namkeen from Jhansi’s most trusted halwai, serving families since 1978.', '1978', '14UP1J53106K1Z4', NULL, NULL, 'uploads/demo/year/sweets/logo.svg', 'uploads/demo/year/sweets/about.jpg', 'sweets@demo.globallife.co.in', '9450034412', NULL, '9450034412', NULL, '58, Sadar Bazaar, near Gandhi Chowk, Jhansi, Uttar Pradesh 284001', 'https://maps.google.com/?q=Shree+Krishna+Mishthan+Bhandar%2C+Jhansi', '{\"monday\":{\"open\":\"08:00\",\"close\":\"22:00\",\"closed\":false},\"tuesday\":{\"open\":\"08:00\",\"close\":\"22:00\",\"closed\":false},\"wednesday\":{\"open\":\"08:00\",\"close\":\"22:00\",\"closed\":false},\"thursday\":{\"open\":\"08:00\",\"close\":\"22:00\",\"closed\":false},\"friday\":{\"open\":\"08:00\",\"close\":\"22:00\",\"closed\":false},\"saturday\":{\"open\":\"08:00\",\"close\":\"22:00\",\"closed\":false},\"sunday\":{\"open\":\"08:00\",\"close\":\"22:00\",\"closed\":false}}', NULL, 'https://facebook.com/', 'https://instagram.com/', NULL, NULL, NULL, NULL, NULL, '{\"videos\":false,\"banner\":true,\"about\":true,\"stats\":true,\"shop\":true,\"services\":true,\"products\":true,\"gallery\":true,\"reviews\":true,\"contact\":true,\"faqs\":true,\"social_media\":true,\"float_whatsapp\":true,\"float_call\":true,\"float_direction\":true,\"float_email\":true}', NULL, 'RK4TORM', 'active', '2025-11-27 16:08:00', '2026-11-27 16:08:00', '2025-11-27 16:08:00', '2025-11-27 16:08:00'),
(@o_vip_microsites+2, @o_users+25, @cities_10, @vip_plans_7, 'Spice Route Family Restaurant', 'Restaurants & Food', 'North Indian & Mughlai Restaurant', 'Sanjay Kapoor', 'spice-route-family-restaurant', 'Spice Route started as a twelve-table eatery in Gomti Nagar and today seats 140 guests across two floors.\n\nOur kitchen is led by Ustad Rafiq Qureshi, a third-generation Awadhi chef. Galouti kebabs are made fresh every hour, the dum biryani is sealed in handi the traditional way, and every gravy is ground in-house. Private dining, birthday parties and corporate lunches are our speciality.', 'Lucknow’s favourite family restaurant for Awadhi kebabs, biryani and North Indian thalis since 2012.', '2012', '27WUR5X8770Y1Z4', NULL, NULL, 'uploads/demo/year/restaurant/logo.svg', 'uploads/demo/year/restaurant/about.jpg', 'restaurant@demo.globallife.co.in', '9415502231', NULL, '9415502231', NULL, '2/45, Vibhuti Khand, Gomti Nagar, Lucknow, Uttar Pradesh 226010', 'https://maps.google.com/?q=Spice+Route+Family+Restaurant%2C+Lucknow', '{\"monday\":{\"open\":\"11:30\",\"close\":\"23:00\",\"closed\":false},\"tuesday\":{\"open\":\"11:30\",\"close\":\"23:00\",\"closed\":false},\"wednesday\":{\"open\":\"11:30\",\"close\":\"23:00\",\"closed\":false},\"thursday\":{\"open\":\"11:30\",\"close\":\"23:00\",\"closed\":false},\"friday\":{\"open\":\"11:30\",\"close\":\"23:00\",\"closed\":false},\"saturday\":{\"open\":\"11:30\",\"close\":\"23:00\",\"closed\":false},\"sunday\":{\"open\":\"11:30\",\"close\":\"23:00\",\"closed\":false}}', NULL, 'https://facebook.com/', 'https://instagram.com/', NULL, NULL, NULL, NULL, NULL, '{\"videos\":false,\"banner\":true,\"about\":true,\"stats\":true,\"shop\":true,\"services\":true,\"products\":true,\"gallery\":true,\"reviews\":true,\"contact\":true,\"faqs\":true,\"social_media\":true,\"float_whatsapp\":true,\"float_call\":true,\"float_direction\":true,\"float_email\":true}', NULL, 'ZXKVNIC', 'active', '2025-11-27 17:53:00', '2026-11-27 17:53:00', '2025-11-27 17:53:00', '2025-11-27 17:53:00'),
(@o_vip_microsites+3, @o_users+34, @cities_5, @vip_plans_7, 'Iron Paradise Fitness Studio', 'Fitness', 'Gym & Personal Training', 'Vikram Reddy', 'iron-paradise-fitness-studio', 'Iron Paradise was founded by national-level powerlifter Vikram Reddy to bring serious training to everyday people.\n\nWe have imported strength equipment, a functional training zone, steam rooms and separate changing areas. Every member gets a free body-composition analysis and a starter plan from our nutritionist.', 'A fully equipped 8,000 sq. ft. gym in Madhapur with certified trainers, CrossFit and nutrition coaching.', '2019', '10I3J1J7020V1Z1', NULL, NULL, 'uploads/demo/year/gym/logo.svg', 'uploads/demo/year/gym/about.jpg', 'gym@demo.globallife.co.in', '9908112456', NULL, '9908112456', NULL, '3rd Floor, Cyber Pearl Building, HITEC City Road, Madhapur, Hyderabad, Telangana 500081', 'https://maps.google.com/?q=Iron+Paradise+Fitness+Studio%2C+Hyderabad', '{\"monday\":{\"open\":\"05:30\",\"close\":\"22:30\",\"closed\":false},\"tuesday\":{\"open\":\"05:30\",\"close\":\"22:30\",\"closed\":false},\"wednesday\":{\"open\":\"05:30\",\"close\":\"22:30\",\"closed\":false},\"thursday\":{\"open\":\"05:30\",\"close\":\"22:30\",\"closed\":false},\"friday\":{\"open\":\"05:30\",\"close\":\"22:30\",\"closed\":false},\"saturday\":{\"open\":\"05:30\",\"close\":\"22:30\",\"closed\":false},\"sunday\":{\"open\":\"05:30\",\"close\":\"22:30\",\"closed\":false}}', NULL, 'https://facebook.com/', 'https://instagram.com/', NULL, NULL, NULL, NULL, NULL, '{\"videos\":false,\"banner\":true,\"about\":true,\"stats\":true,\"shop\":true,\"services\":true,\"products\":true,\"gallery\":true,\"reviews\":true,\"contact\":true,\"faqs\":true,\"social_media\":true,\"float_whatsapp\":true,\"float_call\":true,\"float_direction\":true,\"float_email\":true}', NULL, 'MGXSASL', 'active', '2025-12-15 16:45:00', '2027-06-15 16:45:00', '2025-12-15 16:45:00', '2026-06-08 11:23:00'),
(@o_vip_microsites+4, @o_users+39, @cities_7, @vip_plans_6, 'Glow & Grace Unisex Salon', 'Beauty & Wellness', 'Unisex Salon & Bridal Studio', 'Ritika Sharma', 'glow-grace-unisex-salon', 'Glow & Grace is a 3,000 sq. ft. studio with 12 styling stations, a private bridal suite and a skin lounge.\n\nOur stylists are trained by L’Oréal Professionnel and Schwarzkopf, and we use only sealed, branded products. Hygiene comes first: every tool is sterilised in a UV cabinet between clients.', 'Premium unisex salon in Kothrud — hair, skin, nails and bridal makeovers by certified stylists.', '2017', '18VAGU97511Y1Z8', NULL, NULL, 'uploads/demo/year/salon/logo.svg', 'uploads/demo/year/salon/about.jpg', 'salon@demo.globallife.co.in', '9890245561', NULL, '9890245561', NULL, 'Shop 4-6, Karve Road, Kothrud, Pune, Maharashtra 411038', 'https://maps.google.com/?q=Glow+%26+Grace+Unisex+Salon%2C+Pune', '{\"monday\":{\"open\":\"10:00\",\"close\":\"21:00\",\"closed\":false},\"tuesday\":{\"open\":\"10:00\",\"close\":\"21:00\",\"closed\":true},\"wednesday\":{\"open\":\"10:00\",\"close\":\"21:00\",\"closed\":false},\"thursday\":{\"open\":\"10:00\",\"close\":\"21:00\",\"closed\":false},\"friday\":{\"open\":\"10:00\",\"close\":\"21:00\",\"closed\":false},\"saturday\":{\"open\":\"10:00\",\"close\":\"21:00\",\"closed\":false},\"sunday\":{\"open\":\"10:00\",\"close\":\"21:00\",\"closed\":false}}', NULL, 'https://facebook.com/', 'https://instagram.com/', NULL, NULL, NULL, NULL, NULL, '{\"videos\":false,\"banner\":true,\"about\":true,\"stats\":true,\"shop\":true,\"services\":true,\"products\":true,\"gallery\":true,\"reviews\":true,\"contact\":true,\"faqs\":true,\"social_media\":true,\"float_whatsapp\":true,\"float_call\":true,\"float_direction\":true,\"float_email\":true}', NULL, 'LPTYJMY', 'active', '2025-12-25 16:36:00', '2026-12-25 16:36:00', '2025-12-25 16:36:00', '2026-06-23 12:42:00'),
(@o_vip_microsites+5, @o_users+48, @cities_1, @vip_plans_7, 'Swarnim Jewellers', 'Jewellery', 'Gold, Diamond & Kundan Jewellery', 'Alok Soni', 'swarnim-jewellers', 'Swarnim Jewellers has been crafting bridal and everyday jewellery for Bundelkhand families since 1995.\n\nEvery gold piece is BIS hallmarked with HUID, diamonds come with IGI certificates, and we offer lifetime exchange at the day’s gold rate. Custom designs are made in our own workshop.', 'BIS-hallmarked gold, kundan and diamond jewellery with lifetime exchange, in the heart of Jhansi.', '1995', '20AEWQG7489O1Z3', NULL, NULL, 'uploads/demo/year/jewellery/logo.svg', 'uploads/demo/year/jewellery/about.jpg', 'jewellery@demo.globallife.co.in', '9415187730', NULL, '9415187730', NULL, '14, Manik Chowk, Jhansi, Uttar Pradesh 284002', 'https://maps.google.com/?q=Swarnim+Jewellers%2C+Jhansi', '{\"monday\":{\"open\":\"10:30\",\"close\":\"20:30\",\"closed\":false},\"tuesday\":{\"open\":\"10:30\",\"close\":\"20:30\",\"closed\":true},\"wednesday\":{\"open\":\"10:30\",\"close\":\"20:30\",\"closed\":false},\"thursday\":{\"open\":\"10:30\",\"close\":\"20:30\",\"closed\":false},\"friday\":{\"open\":\"10:30\",\"close\":\"20:30\",\"closed\":false},\"saturday\":{\"open\":\"10:30\",\"close\":\"20:30\",\"closed\":false},\"sunday\":{\"open\":\"10:30\",\"close\":\"20:30\",\"closed\":false}}', NULL, 'https://facebook.com/', 'https://instagram.com/', NULL, NULL, NULL, NULL, NULL, '{\"videos\":false,\"banner\":true,\"about\":true,\"stats\":true,\"shop\":true,\"services\":true,\"products\":true,\"gallery\":true,\"reviews\":true,\"contact\":true,\"faqs\":true,\"social_media\":true,\"float_whatsapp\":true,\"float_call\":true,\"float_direction\":true,\"float_email\":true}', NULL, '4OKHEC9', 'active', '2026-01-14 13:05:00', '2027-01-14 13:05:00', '2026-01-14 13:05:00', '2026-01-14 13:05:00'),
