INSERT INTO `business_faqs` (`id`, `vip_microsite_id`, `question`, `answer`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES
(@o_business_faqs+1, @o_vip_microsites+1, 'Do you deliver at home?', 'Yes, anywhere in Jhansi. Orders placed online are delivered by our own staff the same day.', '0', '1', '2025-11-27 16:08:00', '2025-11-27 16:08:00'),
(@o_business_faqs+2, @o_vip_microsites+1, 'How long do the sweets stay fresh?', 'Milk sweets 3 days in the fridge; dry sweets and namkeen up to 3 weeks.', '1', '1', '2025-11-27 16:08:00', '2025-11-27 16:08:00'),
(@o_business_faqs+3, @o_vip_microsites+1, 'Are your sweets made in pure ghee?', 'Yes — every sweet is made in pure desi ghee.', '2', '1', '2025-11-27 16:08:00', '2025-11-27 16:08:00'),
(@o_business_faqs+4, @o_vip_microsites+2, 'Do you take table reservations?', 'Yes. Call or WhatsApp us; tables are held for 15 minutes past the booking time.', '0', '1', '2025-11-27 17:53:00', '2025-11-27 17:53:00'),
(@o_business_faqs+5, @o_vip_microsites+2, 'Is there parking?', 'Free basement parking for 30 cars and valet on weekends.', '1', '1', '2025-11-27 17:53:00', '2025-11-27 17:53:00'),
(@o_business_faqs+6, @o_vip_microsites+2, 'Do you serve Jain food?', 'Yes, a separate Jain menu is available on request.', '2', '1', '2025-11-27 17:53:00', '2025-11-27 17:53:00'),
(@o_business_faqs+7, @o_vip_microsites+3, 'Is there a trial?', 'Yes, a free 3-day trial pass for first-time visitors.', '0', '1', '2025-12-15 16:45:00', '2025-12-15 16:45:00'),
(@o_business_faqs+8, @o_vip_microsites+3, 'Are there female trainers?', 'Yes, we have two certified female trainers.', '1', '1', '2025-12-15 16:45:00', '2025-12-15 16:45:00'),
(@o_business_faqs+9, @o_vip_microsites+3, 'Is parking available?', 'Free two-wheeler and car parking in the building.', '2', '1', '2025-12-15 16:45:00', '2025-12-15 16:45:00'),
(@o_business_faqs+10, @o_vip_microsites+4, 'Do I need an appointment?', 'Walk-ins are welcome, but booking on WhatsApp guarantees your slot.', '0', '1', '2025-12-25 16:36:00', '2025-12-25 16:36:00'),
(@o_business_faqs+11, @o_vip_microsites+4, 'Do you do home bridal services?', 'Yes, within Pune for bridal packages.', '1', '1', '2025-12-25 16:36:00', '2025-12-25 16:36:00'),
(@o_business_faqs+12, @o_vip_microsites+4, 'Which brands do you use?', 'L’Oréal Professionnel, Schwarzkopf, O3+ and Kryolan.', '2', '1', '2025-12-25 16:36:00', '2025-12-25 16:36:00'),
(@o_business_faqs+13, @o_vip_microsites+5, 'Is your gold hallmarked?', 'Yes, every piece is BIS hallmarked with a 6-digit HUID.', '0', '1', '2026-01-14 13:05:00', '2026-01-14 13:05:00'),
(@o_business_faqs+14, @o_vip_microsites+5, 'Do you offer EMI?', 'Yes, on purchases above ₹50,000 with select bank cards.', '1', '1', '2026-01-14 13:05:00', '2026-01-14 13:05:00'),
(@o_business_faqs+15, @o_vip_microsites+5, 'What are making charges?', 'From 8% on plain gold; quoted per design for kundan and polki.', '2', '1', '2026-01-14 13:05:00', '2026-01-14 13:05:00'),
(@o_business_faqs+16, @o_vip_microsites+6, 'Do you need a prescription?', 'Yes, for scheduled medicines. Upload or WhatsApp a photo of it.', '0', '1', '2026-01-17 12:06:00', '2026-01-17 12:06:00'),
(@o_business_faqs+17, @o_vip_microsites+6, 'Do you give discounts?', 'Flat 10–15% on most medicines and more on monthly refills.', '1', '1', '2026-01-17 12:06:00', '2026-01-17 12:06:00'),
(@o_business_faqs+18, @o_vip_microsites+6, 'Can I return medicines?', 'Unopened strips can be returned within 7 days with the bill.', '2', '1', '2026-01-17 12:06:00', '2026-01-17 12:06:00'),
(@o_business_faqs+19, @o_vip_microsites+7, 'Do you offer EMI?', 'Yes, zero-cost EMI on Bajaj Finserv and major credit cards.', '0', '1', '2026-02-08 14:23:00', '2026-02-08 14:23:00'),
