INSERT INTO `announcements` (`id`, `title`, `body`, `is_active`, `published_by`, `created_at`, `updated_at`) VALUES
(@o_announcements+1, 'Year-end closing schedule', 'Accounts will close the books for 2025 on 31 December. Please submit all pending expense claims by 26 December.\n\nThe office stays closed on 25 December for Christmas.', '1', @o_users+3, '2025-12-01 10:15:00', '2025-12-01 10:15:00'),
(@o_announcements+2, 'Republic Day celebration', 'Flag hoisting at 9:30 am on 26 January at the Gomti Nagar office, followed by breakfast. Families are welcome.', '1', @o_users+3, '2026-01-20 10:15:00', '2026-01-20 10:15:00'),
(@o_announcements+3, 'Holi holiday and office timing', 'The office is closed on 4 March for Holi. On 3 March we close at 4 pm — Happy Holi in advance!', '1', @o_users+3, '2026-03-01 10:15:00', '2026-03-01 10:15:00'),
(@o_announcements+4, 'New financial year — investment declarations', 'Please submit your FY 2026-27 investment declarations (80C, HRA, 80D) to HR by 20 April so TDS can be calculated correctly.', '1', @o_users+3, '2026-04-01 10:15:00', '2026-04-01 10:15:00'),
(@o_announcements+5, 'Welcome Pallavi Dubey', 'Please welcome Pallavi Dubey, who joins Operations as Data Entry Operator today.', '1', @o_users+3, '2026-06-15 10:15:00', '2026-06-15 10:15:00'),
(@o_announcements+6, 'Health check-up camp', 'A free health check-up camp (BP, sugar, lipid profile, eye test) will be held at the office on 22 August from 10 am to 2 pm.', '1', @o_users+3, '2026-08-10 10:15:00', '2026-08-10 10:15:00'),
(@o_announcements+7, 'Diwali bonus and office celebration', 'The Diwali bonus will be paid with the October salary. Office Diwali celebration on 7 November at 4 pm — ethnic wear encouraged!\n\nThe office is closed on 9 November.', '1', @o_users+3, '2026-10-25 10:15:00', '2026-10-25 10:15:00');
